import sys

def main():
    s = sys.stdin.readline().rstrip('\n')
    line = sys.stdin.readline().strip()

    parts = line.split()
    start = int(parts[0])
    end = int(parts[1])
    step = int(parts[2])

    if step == 0:
        print("Zero")
    else:
        print(s[start:end:step])

if __name__ == "__main__":
    main()
